import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Crimson/SeaStore 2021-05-19","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore 2021-05-19","date":"2021-05-19T00:00:00.000Z","updated":"2021-05-19T00:00:00.000Z","tags":["Ceph","自我管理代理","推模型","拉模型","安全性","可靠性","架构设计"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_SeaStore_2021-05-19.md","filePath":"posts/2021/Ceph_Crimson_SeaStore_2021-05-19.md","lastUpdated":1780459816000}'),a={name:"posts/2021/Ceph_Crimson_SeaStore_2021-05-19.md"};function p(r,l,s,n,_,m){return t(),i("div",null,[...l[0]||(l[0]=[o("<p>会议纪要：</p><p>本周的 orchestrator 会议主要讨论了 Ceph 的自我管理代理（self-adm agent）的深入探讨，以及模型选择、架构实现、安全性和可靠性等问题。</p><ol><li><p><strong>自我管理代理（self-adm agent）的深入探讨</strong></p><ul><li>讨论了自我管理代理的需求、收益以及对架构的影响。</li><li>分析了当前 cephadm 中的 reconciliation loop 的扩展性问题，特别是通过 SSH 连接执行任务的效率问题。</li></ul></li><li><p><strong>模型选择：推模型 vs 拉模型</strong></p><ul><li>讨论了使用推模型（push model）和拉模型（pull model）的优劣。</li><li>倾向于使用推模型，通过在每个主机上运行的代理（agent）将信息推送到管理模块（manager module），以提高性能和响应速度。</li></ul></li><li><p><strong>架构和实现细节</strong></p><ul><li>讨论了代理（agent）的职责和如何设计架构以最大化收益。</li><li>考虑了如何处理潜在的竞争条件和失败模式，特别是在部署新守护进程（daemon）时的同步问题。</li></ul></li><li><p><strong>安全性和可靠性</strong></p><ul><li>讨论了如何确保代理（agent）与管理模块（manager module）之间的通信安全，包括使用 API 端点和客户端认证。</li><li>考虑了如何处理主机离线的情况，以及如何确保代理（agent）的可靠运行。</li></ul></li><li><p><strong>未来扩展和升级路径</strong></p><ul><li>讨论了如何设计系统以便未来可以扩展到集群外的客户端。</li><li>考虑了从旧版本升级到新版本时的兼容性和升级路径。</li></ul></li></ol><p>决策事项：</p><ul><li>倾向于采用推模型（push model）来改善系统的扩展性和响应速度。</li><li>需要进一步细化代理（agent）的职责和架构设计，以避免竞争条件和失败模式。</li><li>需要设计一个安全可靠的通信机制，确保代理（agent）与管理模块（manager module）之间的信息交换。</li></ul><p>后续行动计划：</p><ul><li>分配任务给团队成员，进一步细化代理（agent）的设计和实现细节。</li><li>开始实施初步的推模型（push model）原型，并进行测试以验证其性能和可靠性。</li><li>考虑未来的扩展需求，确保设计具有足够的灵活性和可扩展性。</li></ul>",7)])])}const g=e(a,[["render",p]]);export{u as __pageData,g as default};
